WITH session_totals AS (SELECT session_id, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec, COUNT(duration_sec) AS duration_sec_count FROM web_events WHERE HOUR(event_time) BETWEEN 6 AND 9 GROUP BY session_id) SELECT s.id, s.customer_id, st.stddev_duration_sec, st.duration_sec_count FROM sessions s INNER JOIN session_totals st ON s.id = st.session_id WHERE st.stddev_duration_sec > 70 ORDER BY 3 DESC
